"""Confirm the Super Rare brawler purchase offer before closing its modal."""
import numpy as np
from reward_receipts import _find, _valid
HEADER = ''
CROSS = ''


def brawler_offer_close_position(frame):
    if not _valid(frame):
        return None
    if _find(frame, HEADER, (.51,.16,.86,.49)) is None:
        return None
    position=_find(frame, CROSS, (.8,.12,.92,.27))
    if position is None:
        return None
    h,w=frame.shape[:2]
    body=frame[round(h*.155):round(h*.18),round(w*.2):round(w*.72)]
    blue=(body[:,:,0]<70)&(body[:,:,1]>50)&(body[:,:,2]>160)
    purchase=frame[round(h*.765):round(h*.82),round(w*.65):round(w*.83)]
    green=(purchase[:,:,0]<110)&(purchase[:,:,1]>145)&(purchase[:,:,2]<110)
    cx,cy=position
    button=frame[max(0,round(cy-h*.035)):round(cy+h*.035),round(cx-w*.026):round(cx+w*.026)]
    red=(button[:,:,0]>170)&(button[:,:,1]<100)&(button[:,:,2]<100)
    if not blue.size or blue.mean()<.8 or not green.size or green.mean()<.6 or not red.size or red.mean()<.3:
        return None
    return round(cx),round(cy)
